preset.frame_eqs_eel:
vb = vb*0.95 + (1-vb)*pow(bass,2)*0.02;
vvb = vvb*0.95 + (1-vvb)*vb*0.01;
vm = vm*0.95 + (1-vm)*pow(mid,2)*0.02;
vvm = vvm*0.95 + (1-vvm)*vm*0.01;
vt = vt*0.95 + (1-vt)*pow(treb,2)*0.02;
vvt = vvt*0.95 + (1-vvt)*vt*0.01;
vvb = min(1,max(0,vvb));
vvm = min(1,max(0,vvm));
vvt = min(1,max(0,vvt));

q1 = vvb*2;//0.5 + vb - vvb;
q2 = vvm*2;//0.5 + vm - vvm;
q3 = vvt*2;//0.5 + vt - vvt;

v=2;

bb = bb - vvb*v;
mm = mm - vvm*v;
tt = tt - vvt*v;

q4 = bb;
q5 = mm;
q6 = tt;

pi3 = 3.1415*2*0.3333;

t = (q4+q5+q6)*0.005;
c=3;
r = sin(t)*c;

g = sin(t+pi3)*c;

b = sin(t-pi3)*c;

ob_r = min(1,max(0,r));
