ob_b = min(1,max(0,b));

preset.pixel_eqs_eel:
pi = asin(1);

x = x-0.5;
y = y- 0.5;

d = (q4-q6)*0.4 +  (rad-0.3)*(q1-q3)*2 + pi;
xx = sin(d)*x - cos(d)*y;
yy = cos(d)*x + sin(d)*y;


x = xx;
y = yy;


t = time*.2;
xh = x;
yh = y;

w = (q4-q6)*0.8;
m = -1 + q2*2;
wv = pi-sin(w)*m;
wh = pi-cos(w)*m;
d = 8*sqrt(q2);
ww = 1.2;
ddx = sin(2*pi - wv -(x)*ww);
ddy = sin(2*pi - wh -(y)*ww);
rx = if(above(ddx*ddy,0),sin(wv)/ddx,0);
ry = if(above(ddy*ddy,0),sin(wh)/ddy,0);

v = -(q2)*.1*(d/ww);

ax = ax + sin(w)*v;
ay = ay + cos(w)*v;

vx = if(equal(rx*ry,0),0,ax);
vy = if(equal(rx*ry,0),0,ay);

dx = (-xh*rx*ry*d + vx*.001);
dy = (-yh*rx*ry*d + vy*.001);

